[CmdletBinding()]
param([string]$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..\..\..\..')).Path, [string]$DataRoot = (Join-Path $env:TEMP ('ERPPrototype-ProductionReview-Test-' + [Guid]::NewGuid().ToString())))
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Import-Module (Join-Path $PSScriptRoot 'ProductionReview.psm1') -Force
Import-Module (Join-Path (Split-Path -Parent $PSScriptRoot) 'AITeamCodex.psm1') -Force
$checks = New-Object Collections.Generic.List[object]
function Assert-Check { param([string]$Name,[scriptblock]$Action) try { & $Action; $checks.Add([pscustomobject]@{ name=$Name; pass=$true; detail=$null }) } catch { $checks.Add([pscustomobject]@{ name=$Name; pass=$false; detail=$_.Exception.Message }) } }
Assert-Check 'schemas parse and production result is Structured Outputs compatible' { Get-Content (Join-Path $RepoRoot '.ai\schemas\production-review-result.schema.json') -Raw | ConvertFrom-Json | Out-Null; if (-not (Test-AITeamCodexOutputSchema (Join-Path $RepoRoot '.ai\schemas\production-review-result.schema.json')).pass) { throw 'Structured Outputs schema validation failed.' }; Get-Content (Join-Path $RepoRoot '.ai\schemas\review-record.schema.json') -Raw | ConvertFrom-Json | Out-Null }
$head = (& git -C $RepoRoot rev-parse HEAD).Trim()
Assert-Check 'UUID, Base/Candidate, ancestry, diff digest and repository identity' { $p=Resolve-ProductionReviewRepository -RepoRoot $RepoRoot -BaseSha $head -CandidateSha $head; if (-not $p.candidateMatch -or -not $p.baseAncestorOfCandidate -or $p.candidateDiffDigest.Length -ne 64 -or $p.workspaceFingerprint.Length -ne 64) { throw 'Preflight contract did not hold.' } }
$created = $null
Assert-Check 'atomic record creation and duplicate ID rejection' { $id=[Guid]::NewGuid().ToString(); $script:created=New-ProductionReviewRecord -MissionId 'deterministic-test' -RepoRoot $RepoRoot -BaseSha $head -CandidateSha $head -ReviewId $id -DataRoot $DataRoot; $duplicate=$false; try { New-ProductionReviewRecord -MissionId 'duplicate' -RepoRoot $RepoRoot -BaseSha $head -CandidateSha $head -ReviewId $id -DataRoot $DataRoot | Out-Null } catch { $duplicate=$true }; if (-not $duplicate) { throw 'Duplicate review ID was not rejected.' } }
Assert-Check 'stale revision rejection' { $out=[ordered]@{ status='TEST'; mainDecision='TEST'; evidenceStrength='UNKNOWN'; confirmedFindings=@(); rejectedFindings=@(); unresolvedFindings=@(); fixedFindings=@(); acceptedRisks=@(); candidateAccepted=$false; decisionTimestamp=[DateTime]::UtcNow.ToString('o'); evidenceReferences=@() }; Set-ProductionReviewOutcome -ReviewId $script:created.record.identity.reviewId -ExpectedRevision 1 -Outcome $out -DataRoot $DataRoot | Out-Null; try { Set-ProductionReviewOutcome -ReviewId $script:created.record.identity.reviewId -ExpectedRevision 1 -Outcome $out -DataRoot $DataRoot | Out-Null; throw 'Stale update unexpectedly succeeded.' } catch { if ($_.Exception.Message -notmatch 'Stale') { throw } } }
Assert-Check 'malformed and extremely long anchors fail cleanly' { $bad=Test-ProductionReviewAnchor -Anchor ([pscustomobject]@{relativePath='..\outside';startLine=1;endLine=1}) -RepoRoot $RepoRoot; $long=Test-ProductionReviewAnchor -Anchor ([pscustomobject]@{relativePath=('x'*301);startLine=1;endLine=1}) -RepoRoot $RepoRoot; if ($bad.pass -or $long.pass) { throw 'Unsafe anchor passed.' } }
Assert-Check 'transport remains read-only with documented read capability' { $transport=Get-ProductionReviewerTransport; if ($transport.sandboxMode -ne 'read-only' -or @($transport.sandboxPermissions).Count -ne 1 -or $transport.sandboxPermissions[0] -ne 'disk-full-read-access') { throw 'Production transport is not the intended narrow read-only configuration.' } }
Assert-Check 'telemetry parses reasoning, tool failures, models, and reported versus derived totals' { $events=Join-Path $DataRoot 'events.jsonl'; @('{"type":"thread.started","thread_id":"thread-test"}','{"type":"turn.started","model":"actual-model"}','{"type":"item.started","item":{"type":"command_execution"}}','{"type":"turn.completed","usage":{"input_tokens":10,"cached_input_tokens":4,"output_tokens":3,"reasoning_output_tokens":2,"total_tokens":13}}') | Set-Content $events -Encoding UTF8; $stderr=Join-Path $DataRoot 'stderr.txt'; 'exec_command failed for test command' | Set-Content $stderr -Encoding UTF8; $u=Get-AITeamCodexUsageFromEvents $events; $t=Get-ProductionReviewTelemetry -EventsPath $events -StderrPath $stderr -CodexUsage $u -Execution ([pscustomobject]@{modelAttempted=$true;elapsedMilliseconds=1}) -RequestedModel 'requested-model'; if ($u.reasoningTokens -ne 2 -or $t.reasoningTokens -ne 2 -or $t.totalTokensReported -ne 13 -or $t.totalTokensDerived -ne 13 -or $t.toolAttempts -ne 2 -or $t.toolFailures -ne 1 -or $t.requestedModel -ne 'requested-model' -or $t.actualModel -ne 'actual-model') { throw 'Observed telemetry was not parsed with the required semantics.' } }
Assert-Check 'process-bound correlation becomes strong without optional prompt marker' { $events=Join-Path $DataRoot 'correlation.jsonl'; '{"type":"thread.started","thread_id":"thread-test"}' | Set-Content $events -Encoding UTF8; $c=Get-ProductionReviewSessionCorrelation -EventsPath $events -ExpectedCwd $RepoRoot -InvocationCwd $RepoRoot -CandidateSha $head -AttemptMarker 'm'; if ($c.strength -ne 'STRONG' -or -not $c.invocationCwdMatch -or -not $c.candidateIdentityBound) { throw 'Process-bound correlation was not strong.' } }
Assert-Check 'previous infrastructure failure pattern becomes SMOKE_FAILED' { $pre=[pscustomobject]@{candidateMatch=$true;baseAncestorOfCandidate=$true}; $validation=[pscustomobject]@{pass=$true}; $correlation=[pscustomobject]@{strength='PARTIAL';threadIds=@()}; $telemetry=[pscustomobject]@{inputTokens=1;outputTokens=1}; $post=[pscustomobject]@{pass=$true}; $reviewer=[pscustomobject]@{disposition='EVIDENCE_REQUIRED'}; $smoke=Test-ProductionSmokeInfrastructure -Preflight $pre -Validation $validation -Correlation $correlation -Telemetry $telemetry -Postflight $post -ReviewerResult $reviewer; if ($smoke.pass -or $smoke.failureClass -ne 'INFRASTRUCTURE_TRANSPORT') { throw 'Infrastructure failure was incorrectly accepted.' } }
Assert-Check 'benchmark and production distinction plus requirement superseded semantics' { $b=New-ProductionReviewRecord -MissionId 'benchmark' -Mode benchmark -RepoRoot $RepoRoot -BaseSha $head -CandidateSha $head -DataRoot $DataRoot; if ($b.record.identity.mode -ne 'benchmark') { throw 'Benchmark mode was lost.' }; $feedback=[ordered]@{ type='requirement_superseded'; timestamp=[DateTime]::UtcNow.ToString('o'); evidence='decision update'; affected='test' }; if ($feedback.type -eq 'false_positive') { throw 'Superseded requirement misclassified.' } }
Assert-Check 'production code has no Router, permanent Lead, or qualification oracle dependency' { $content=Get-Content (Join-Path $PSScriptRoot 'ProductionReview.psm1') -Raw; foreach($forbidden in @('AITeamLocalRouter','lead-integrator','oracles-v3','routing-rules')) { if ($content -match $forbidden) { throw "Forbidden production dependency: $forbidden" } } }
$failed = 0; foreach ($check in $checks) { if (-not $check.pass) { $failed++ } }
$result=[pscustomobject]@{ pass=($failed -eq 0); checks=$checks.ToArray(); dataRoot=$DataRoot }; $result | ConvertTo-Json -Depth 10; if(-not $result.pass){exit 1}
